Method.Implementation:
	set tSC = $$$OK

	set pSourceDir = ..Directory	
	if ( ##class(%File).DirectoryExists(pSourceDir))
	{
			Set file=##class(%File).%New(pSourceDir _ "../" _ "TestNetworkTransRecvCount-" _ $ZDATE($HOROLOG,3) _"_" _ $ZTIME($HOROLOG,1) _".txt")

   			Do file.Open("WSN")

			Do file.WriteLine( $NAMESPACE _", " _ $ZDATE($HOROLOG,3) _"_" _ $ZTIME($HOROLOG,1))
			set glbNm = "TCP" _ ..Port _ "_" _$ZDATE( ($PIECE($HOROLOG,",",1) ), 3)
			set glbNmF5 = "TCP" _ ..PortF5 _ "_" _$ZDATE( ($PIECE($HOROLOG,",",1)), 3)
			 Do file.WriteLine( "Today's Count from Globals: " _^TestNetworkTransRecvCount(glbNm) _" / " _^TestNetworkTransRecvCount(glbNmF5))
			 if ($NUMBER(^TestNetworkTransRecvCount(glbNm)) '= $NUMBER(^TestNetworkTransRecvCount(glbNmF5)))
			 {
				 Do file.WriteLine( "Total for today do not match: " _ ^TestNetworkTransRecvCount(glbNm) _" '= " _ ^TestNetworkTransRecvCount(glbNmF5))
			 }
			 else {
				 Do file.WriteLine( "Total for today match: " _ ^TestNetworkTransRecvCount(glbNm))
			 }

			 set glbNm = "TCP7103"_ "_" _$ZDATE( ($PIECE($HOROLOG,",",1) - 1), 3)
			 set glbNmF5 = "TCP7104"_ "_" _$ZDATE( ($PIECE($HOROLOG,",",1) - 1), 3)
			 Do file.WriteLine( "Count from Globals for yesterday: " _^TestNetworkTransRecvCount(glbNm) _" / " _^TestNetworkTransRecvCount(glbNmF5))
			 if ($NUMBER(^TestNetworkTransRecvCount(glbNm),"I") = $NUMBER(^TestNetworkTransRecvCount(glbNmF5),"I"))
			 {


						Do file.WriteLine( "  Delete files from " _ pSourceDir)
					    set num = 0
						Set tSC = ##class(%File).FileSetExecute(.tHandle, pSourceDir, glbNm _"*")

						If $$$ISOK(tSC) {
							Set tAtEnd = 0
							For {
								Set tSC = ##class(%File).FileSetFetch(.tHandle, .tRow, .tAtEnd)
								If '$$$ISOK(tSC)!($ListLength(tRow)<6) Quit
								set fNm = $List(tRow, 1)
								set tSC = ##class(%File).Delete(fNm)
								WRITE "  -- " _ fNm _": " _ tSC
								Do $INCREMENT(num)
							}
						}
						else
						{
							Do file.WriteLine("FileSetExecute: " _ tSC)
						}
						Do file.WriteLine( "  Deleted: " _ num _ " files ")

			 }		
			 else
			 {
				 Do file.WriteLine( "Number of HL7 messages between two inbound services do not match: "  _^TestNetworkTransRecvCount(glbNm) _" / " _^TestNetworkTransRecvCount(glbNmF5))
			 }
			 Do file.WriteLine( "-=-")
	}
	return tSC
